from pathlib import Path
import json
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from pypdf import PdfReader
b=Path.cwd();out=b/'output/pdf';out.mkdir(parents=True,exist_ok=True);styles=getSampleStyleSheet();styles['BodyText'].fontSize=10;styles['BodyText'].leading=14
r=json.loads((b/'artifacts/runs/nepal-syapru-004/result.json').read_text());s=r['summary']
def p(t,style='BodyText'):return Paragraph(t,styles[style])
def footer(c,d):c.setFont('Helvetica',8);c.drawString(42,25,'SatQuery Flood Impact | Research prototype | 15 October 2026');c.drawRightString(A4[0]-42,25,str(d.page))
def build(name,items):
 path=out/name;SimpleDocTemplate(str(path),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=38,bottomMargin=42).build(items,onFirstPage=footer,onLaterPages=footer);return path
metrics=[['Saved calculation','Official AOI result'],['Water-candidate area',f"{s['new_water_m2']:,.0f} m2"],['Intersected buildings',str(s['exposed_buildings'])],['Intersected road / bridge length',f"{s['exposed_road_m']:.2f} m"],['Intersected bridge features',str(s['exposed_bridge_features'])],['Debris-candidate area',f"{s['debris_candidate_m2']:,.0f} m2"],['Settlement isolation','Unresolved; not zero']]
table=Table(metrics,colWidths=[260,240]);table.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e4e4e4')),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('BOTTOMPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,0),(-1,-1),.3,colors.lightgrey)]))
items=[p('Nepal flood impact | Situation report','Title'),p('Syapru Besi | Event date: 26 August 2026','Heading2'),p('UNVALIDATED CANDIDATES - not confirmed damage or road closures'),Spacer(1,14),p('Evidence scope','Heading2'),p('Frozen run nepal-syapru-004. Sentinel-1D observations: 16 and 28 August 2026; Sentinel-2: 12 and 27 August. Historical OpenStreetMap snapshot: 27 July. Analysis grid: 10 m, EPSG:32645. Paired valid SAR coverage: 31,838 pixels within the irregular official AOI; the raster rectangle also contains masked pixels.'),Spacer(1,12),table,Spacer(1,12),p('Interpretation and limits','Heading2'),p('Water candidates come from fixed SAR thresholds. The debris proxy detects vegetation loss to bare ground with SAR change; it may confuse clearing or agriculture and miss deposits on already bare ground. Intersections indicate exposure, not asset damage. Unknown observations, boundary-truncated road components and unverified snapping prevent a definitive settlement-isolation conclusion.'),p('Reference check','Heading2'),p('One-AOI diagnostic agreement with EMSR927 landslide mapping: IoU 0.328, F1 0.494, recall 0.328. Reference class, timing and resolution differ. This is not independent validated debris accuracy. No compatible water accuracy score is claimed.'),p('Traceability','Heading2'),p('Inspect result.json, exposure.csv, debris-exposure.csv, connectivity.json, topology-audit.json and freeze.json in Workspace. This report uses the official AOI run; automatic rectangular-area runs have different coverage and counts. Sources: Copernicus Sentinel / DEM; OpenStreetMap contributors and HeiGIT; Copernicus EMS (evaluation only).')]
a=build('nepal-situation-report.pdf',items);assert len(PdfReader(a).pages)==1
items=[p('SatQuery Flood Impact','Title'),p('Technical report | IIT Mandi Track B','Heading2'),p('1. Objective and scope','Heading2'),p('The isolated local application at port 8770 estimates flood-related candidates, infrastructure exposure and possible access disruption. The original SatQuery remains on port 8767. This prototype is not a validated emergency response system. The selected AI component is an English/Nepali evidence copilot; no trained flood-segmentation performance is claimed.'),p('2. Inputs and provenance','Heading2'),p('The Nepal reference case uses matched Sentinel-1D acquisitions from 16/28 August 2026, relative orbit 85 ascending. Copernicus Sentinel Hub processes GRD with terrain correction and Copernicus DEM30; processing requests and output hashes are retained. Optical observations are Sentinel-2 L2A. Historical OSM is acquired with snapshot timestamps and original road versions. EMSR927 damage labels are evaluation-only and are excluded from prediction and threshold selection.'),p('3. Processing','Heading2'),p('Scene identity, VV/VH bands, units, grids, orbit and dates are checked. Linear gamma0 is converted to dB; nonfinite, nonpositive, shadow, out-of-range incidence and NoData pixels are masked. Water candidates require post-event VV below -17 dB, pre-event VV not below that threshold, and a drop of at least 3 dB. These are uncalibrated defaults. Two-date water is not proof of permanent water.'),p('The debris proxy requires vegetation-to-bare-ground optical change with a SAR change. Cloud-invalid pixels are excluded. It is not a trained classifier. Automatic acquisition examines up to three nearby optical dates on each side within 14 days and selects the greatest clear coverage; this bounded search may miss a better scene.'),p('4. Exposure and access','Heading2'),p('Geometries are intersected in a projected metre CRS. Building counts, road lengths and bridge features retain source IDs. Historical OSM node IDs define junctions, so crossing lines are not automatically connected. Directed road access is compared before/after assumed candidate disruptions. Nearest-node settlement/hospital snapping is limited to 200 m; turn restrictions are not modelled. Network boundaries and unobserved roads retain uncertainty. No confirmed closure or isolation is inferred from the current Nepal result.'),PageBreak(),p('5. Interface and AI','Heading2'),p('Workspace exposes area/date inputs, background progress, saved runs, imagery, layers, downloads and questions. Evidence separates software verification from diagnostic reference comparisons. Qwen3-0.6B selects a topic; bilingual templates insert only saved calculations and source pointers. Routing scored 9/12 development questions before guardrails. This is not independent testing or unrestricted reasoning. Users can override topics; Nepali wording needs human review. Casualty/evacuation claims are unsupported.'),p('6. Evaluation','Heading2'),p('The official AOI frozen run reports 36,100 m2 water candidates, one intersected building, 87.40 m intersected road/bridge length and two bridge features. Debris candidates cover 212,300 m2. One-AOI comparison with EMSR927 landslides yields IoU 0.3279, F1 0.4939, precision 0.9948 and recall 0.3285. This diagnostic has class, time and resolution differences and low recall; no threshold changes were made after scoring. It cannot establish generalization. Water has no compatible accuracy score.'),p('Software checks cover grid/orbit/date contracts, graph cases, exposure, tiled pixelwise equivalence, frozen-evidence integrity and job-state failures. The current regression suite has 69 passing tests. Tests do not prove real road closures or prediction accuracy. Full arrays remain in memory; automatic requests are bounded to one million 10 m pixels and 2500 pixels per side.'),p('7. Reproducibility and current acceptance','Heading2'),p('Run IDs cannot overwrite prior evidence. Outputs include GeoTIFF, GeoJSON, feature CSVs, calculation JSON, reports and SHA-256 hashes. Provider credentials stay in ignored local configuration. The CLI water/exposure and automatic topology/optical stages have completed real runs. A fresh integrated Workspace API job completed with SAR, optical/debris proxy, historical topology and frozen outputs. Browser visual verification, resource measurements, Nepali review and demo recording remain pending at report generation. See the current machine verification records for subsequent changes.'),p('8. Attribution, reuse and limitations','Heading2'),p('Sources: Copernicus Sentinel and Copernicus DEM; OpenStreetMap contributors (ODbL) through HeiGIT/ohsome; Copernicus EMS reference products (checking only); Qwen/Qwen3-0.6B, pinned revision c1899de289a04d12100db370d81485cdf75e47ca. The visual foundation derives from the existing SatQuery application; preserve its MIT notice. Organizer permission for existing-code reuse was not established and must not be implied. No repository publication or submission has been performed.'),p('Official specification source: multimodal-ai-hackathon-2026-7.devpost.com; local audit: docs/official-spec-audit.md. Model, imagery and OSM request provenance accompany the local evidence. Full upstream distribution terms must be preserved when publishing.')]
c=build('technical-report.pdf',items);assert len(PdfReader(c).pages)<=6
print(a,len(PdfReader(a).pages));print(c,len(PdfReader(c).pages))
